changes.content:
types:
  hr_team:
    fields:
      id: { kind: string, required: true }
      name: { kind: string, required: true }
  hr_employee:
    fields:
      id: { kind: string, required: true }
      createdAt: { kind: string, required: true }
      updatedAt: { kind: string, required: true }
      firstName: { kind: string, required: true }
      lastName: { kind: string, required: true }
      jobTitle: { kind: string, required: true }
      email: { kind: string, required: true }
      availableAnnualLeaveDays: { kind: number, required: true }
      teamId: { kind: string, required: true }
  hr_time_off:
    fields:
      id: { kind: string, required: true }
      createdAt: { kind: string, required: true }
      updatedAt: { kind: string, required: true }
      employeeId: { kind: string, required: true }
      timeOffType: { kind: enum, values: [Annual, Sick, Casual], required: true }
      startsAt: { kind: string, required: true }
      endsAt: { kind: string, required: true }
      notes: { kind: string }
      status: { kind: enum, values: [Pending, Approved, Rejected], required: true }
